func (e *EditorConfig) editorAppendRow(s string) {
    row := EditorRow{
        chars:  s,
        render: make([]byte, len(s)),
    }
    e.cx = 0
    e.editorUpdateRow(&row)
    e.rows = append(e.rows, row)
    e.numrows++
}

